#!/usr/bin/env bash
#
# Adds five WWI Espionage-Act-era political prisoners identified as missing
# during a coverage audit against Stephen M. Kohn, "American Political
# Prisoners: Prosecutions under the Espionage and Sedition Acts" (Praeger,
# 1994) and related primary sources. The database already contains the bulk
# of the register in that book; these are narrative/state/acquitted-but-jailed
# cases the register import did not cover.
#
# Safe to re-run: prisoner:add refuses to create a duplicate by name
# (each command tolerates the duplicate-exists exit code so the script
# continues to the next prisoner instead of aborting).
#
# Run from the repo root:  bash database/data/add-espionage-era-gaps.sh

set -euo pipefail
cd "$(dirname "$0")/../.."

# 1. Ernest Gellert — socialist conscientious objector who died in military
#    confinement at Fort Hancock, NJ (brother of the artist Hugo Gellert).
php artisan prisoner:add '{"name":"Ernest Gellert","first_name":"Ernest","last_name":"Gellert","description":"Ernest Gellert was a Hungarian-American socialist and conscientious objector, the younger brother of the radical artist Hugo Gellert. Drafted in 1917, he refused military service on grounds of conscience and was confined at Fort Hancock on Sandy Hook, New Jersey, where he was made to stand at the edge of his own grave-like pit as punishment. On March 8, 1918, he was found shot dead while under military confinement. The Army ruled the death a suicide committed to protest the treatment of conscientious objectors, though the circumstances have long been questioned. His death became a rallying point for critics of the brutal treatment of objectors in World War I military prisons.","state":"New Jersey","gender":"Male","death_date":"1918-03-08","ideologies":["Socialism","Pacifism","Anti-War"],"era":"1910s","in_custody":false,"released":false,"cases":[{"institution_name":"Fort Hancock","institution_city":"Sandy Hook","institution_state":"New Jersey","charges":"Refusal of military service as a conscientious objector after being drafted in World War I","convicted":"Died in military confinement before final disposition","sentence":"Held in military confinement at Fort Hancock; died in custody on March 8, 1918"}]}' || true

# 2. Arthur C. Townley — Nonpartisan League founder; state conviction for
#    conspiracy to discourage enlistments; served 90 days.
php artisan prisoner:add '{"name":"Arthur C. Townley","first_name":"Arthur","middle_name":"Charles","last_name":"Townley","description":"Arthur C. Townley was the founder of the Nonpartisan League, the agrarian political movement that swept North Dakota and the upper Midwest during World War I. A former Socialist Party organizer, Townley built the League into a force that captured the North Dakota state government in 1918. Because some League pamphlets questioned the war effort, Townley and League organizer Joseph Gilbert were convicted in Jackson County, Minnesota, in 1919 of conspiracy to discourage enlistments. After the Minnesota Supreme Court upheld the conviction in 1921, Townley served a 90-day sentence in the Jackson County jail. His prosecution is remembered as one of the signature political trials of the wartime hysteria against farm and labor radicals.","state":"North Dakota","gender":"Male","birthdate":"1880-12-18","death_date":"1959-11-07","ideologies":["Agrarian populism","Socialism"],"affiliation":["Nonpartisan League"],"era":"1910s","in_custody":false,"released":true,"cases":[{"institution_name":"Jackson County Jail","institution_city":"Jackson","institution_state":"Minnesota","charges":"Conspiracy to discourage enlistments (Minnesota wartime sedition prosecution over Nonpartisan League pamphlets)","convicted":"Yes — upheld by the Minnesota Supreme Court in 1921","sentence":"90 days in the Jackson County jail, served in 1921 after the appeal failed","imprisoned_for_days":90}]}' || true

# 3. John Schrag — Kansas Mennonite farmer nearly lynched on Armistice Day
#    1918, jailed awaiting a federal Espionage Act trial, acquitted.
php artisan prisoner:add '{"name":"John Schrag","first_name":"John","last_name":"Schrag","description":"John Schrag was a prosperous Swiss-Mennonite farmer from Harvey County, Kansas, whose faith forbade supporting war. Because he refused to buy Liberty Bonds, a mob in Burrton, Kansas seized him during the Armistice Day celebration on November 11, 1918, doused him with yellow paint, and tried to force him to carry the flag. When the flag fell to the ground he was accused of desecrating it, and he escaped lynching only because a local officer held off the crowd at gunpoint and got him into the town jail. He was then held in the Harvey County jail at Newton and charged under the Espionage Act with showing disrespect to the flag. At his federal trial in December 1918 he was found not guilty, the court noting that the law did not require anyone to salute the flag. His case became one of the best documented examples of wartime mob violence against the peace churches.","state":"Kansas","gender":"Male","ideologies":["Pacifism","Religious nonresistance"],"affiliation":["Mennonite Church"],"era":"1910s","in_custody":false,"released":true,"cases":[{"institution_name":"Harvey County Jail","institution_city":"Newton","institution_state":"Kansas","charges":"Espionage Act charge of showing disrespect to the American flag after refusing to buy war bonds","arrest_date":"1918-11-11","convicted":"No — acquitted (December 1918)","sentence":"Held in the Burrton town jail and then the Harvey County jail at Newton for several weeks awaiting federal trial; acquitted"}]}' || true

# 4. Emanuel Baltzer — lead defendant among ~27 German-Russian socialist
#    farmers (Baltzer v. United States); imprisoned at Leavenworth until the
#    government confessed error.
php artisan prisoner:add '{"name":"Emanuel Baltzer","first_name":"Emanuel","last_name":"Baltzer","description":"Emanuel Baltzer was the lead defendant among roughly two dozen German-Russian socialist farmers from South Dakota prosecuted under the Espionage Act in 1918. Their offense was signing and circulating a petition to the governor that complained about how draft quotas were apportioned among counties, objected to war debt, and threatened to vote him out of office. Convicted, fined, and sent to the federal penitentiary at Leavenworth, the farmers appealed to the Supreme Court in Baltzer v. United States. Justice Oliver Wendell Holmes drafted a forceful dissent defending their right to petition, and rather than allow it to be published the government confessed error, the case was sent back, and the charges were dropped in 1919. The suppressed Holmes dissent, unpublished for decades, is now seen as a milestone on his path to the modern First Amendment.","state":"South Dakota","gender":"Male","ideologies":["Socialism","Agrarian populism"],"era":"1910s","in_custody":false,"released":true,"cases":[{"institution_name":"United States Penitentiary, Leavenworth","institution_city":"Leavenworth","institution_state":"Kansas","charges":"Espionage Act — obstructing the draft by petitioning the governor of South Dakota over draft quotas and war policy","convicted":"Yes — the government later confessed error before the Supreme Court and the case was dismissed on remand (1919)","sentence":"Fined and imprisoned at Leavenworth pending appeal; released after the confession of error in Baltzer v. United States"}]}' || true

# 5. Claus Gunderson — 90 days in the Cass County (ND) jail for abusive
#    language about the Red Cross (Judge Charles F. Amidon, 1918).
php artisan prisoner:add '{"name":"Claus Gunderson","first_name":"Claus","last_name":"Gunderson","description":"Claus Gunderson was a North Dakota man prosecuted in federal court in 1918, during the wave of Espionage Act cases heard by Judge Charles F. Amidon in Fargo. He was convicted for using language described as insulting and abusive toward the Red Cross, its work, and its workers, and Judge Amidon sentenced him to ninety days in the Cass County jail. His case is one of the small-town prosecutions documented in studies of the Espionage and Sedition Acts in North Dakota, where personal feuds and wartime hysteria turned stray remarks into federal crimes.","state":"North Dakota","gender":"Male","era":"1910s","in_custody":false,"released":true,"cases":[{"institution_name":"Cass County Jail","institution_city":"Fargo","institution_state":"North Dakota","charges":"Federal wartime prosecution for insulting and abusive language about the Red Cross and its workers","convicted":"Yes","sentence":"90 days in the Cass County jail (sentenced by Judge Charles F. Amidon, 1918)","imprisoned_for_days":90}]}' || true

echo
echo "Done. Five Espionage-Act-era prisoners added (duplicates are skipped automatically)."
